using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = "gpt-4o-mini-2024-07-18";

// --- Build the chat client through MEAI ---
IChatClient chatClient = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// --- Define agent tools ---
var notepad = new Notepad();
var tools = new AITool[]
{
    AIFunctionFactory.Create(
        WebSearchTool.SearchAsync,
        nameof(WebSearchTool.SearchAsync),
        "Searches the web for a query and returns a list of result snippets. Use this to find information on a topic."),
    AIFunctionFactory.Create(
        notepad.AddNote,
        nameof(notepad.AddNote),
        "Saves a research note with a title and body. Use this to record important findings."),
    AIFunctionFactory.Create(
        notepad.GetNotes,
        nameof(notepad.GetNotes),
        "Returns all saved research notes so far."),
};

// --- Create the agent with Microsoft.Agents.AI ---
var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research assistant. When given a topic:
        1. Use the SearchAsync tool to search the web for relevant information (2-3 searches with different queries).
        2. Use AddNote to save key findings as you go.
        3. After researching, use GetNotes to review everything you collected.
        4. Provide a well-structured summary of your findings, citing the sources you found.
        Be thorough but concise. Focus on factual, up-to-date information.
        """,
    name: "ResearchAgent",
    description: "An AI agent that researches topics by searching the web and summarizing findings.",
    tools: tools);

// --- Run the agent ---
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║       Research Agent (type 'exit' to quit)║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

var session = await agent.CreateSessionAsync();
var runOptions = new ChatClientAgentRunOptions(
    new ChatOptions { Temperature = 0f, MaxOutputTokens = 2048 })
{
    MaximumIterations = 10,
};

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Topic> ");
    Console.ResetColor();

    var input = Console.ReadLine();
    if (string.IsNullOrWhiteSpace(input) || input.Equals("exit", StringComparison.OrdinalIgnoreCase))
    {
        break;
    }

    Console.WriteLine();
    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("Researching...");
    Console.ResetColor();

    try
    {
        var response = await agent.RunAsync(input, session, runOptions);

        Console.ForegroundColor = ConsoleColor.Green;
        Console.WriteLine();
        foreach (var message in response.Messages)
        {
            if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
            {
                Console.WriteLine(message.Text);
            }
        }
        Console.ResetColor();
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.WriteLine($"Error: {ex.Message}");
        Console.ResetColor();
    }

    notepad.Clear();
    Console.WriteLine();
}

Console.WriteLine("Goodbye!");

// =============================================================================
// Tools
// =============================================================================

/// <summary>
/// Simulated web search tool. Replace the implementation with a real search API
/// (e.g., Bing Search, Google Custom Search) for production use.
/// </summary>
static class WebSearchTool
{
    private static readonly HttpClient s_http = new();

    public static async Task<string> SearchAsync(
        [Description("The search query string")] string query,
        CancellationToken cancellationToken = default)
    {
        try
        {
            // Use DuckDuckGo Instant Answer API (free, no key required)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

            using var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.Add("User-Agent", "ResearchAgent/1.0");

            using var response = await s_http.SendAsync(request, cancellationToken);
            response.EnsureSuccessStatusCode();

            using var doc = await JsonDocument.ParseAsync(
                await response.Content.ReadAsStreamAsync(cancellationToken), cancellationToken: cancellationToken);

            var root = doc.RootElement;
            var sb = new StringBuilder();
            sb.AppendLine($"Search results for: \"{query}\"");
            sb.AppendLine();

            // Abstract (main summary)
            var abstractText = root.GetProperty("AbstractText").GetString();
            var abstractSource = root.GetProperty("AbstractSource").GetString();
            var abstractUrl = root.GetProperty("AbstractURL").GetString();

            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                sb.AppendLine($"**{abstractSource}**: {abstractText}");
                sb.AppendLine($"  Source: {abstractUrl}");
                sb.AppendLine();
            }

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                var count = 0;
                foreach (var topic in topics.EnumerateArray())
                {
                    if (count >= 5) break;
                    var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    var firstUrl = topic.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;
                    if (!string.IsNullOrWhiteSpace(text))
                    {
                        sb.AppendLine($"- {text}");
                        if (!string.IsNullOrWhiteSpace(firstUrl))
                            sb.AppendLine($"  URL: {firstUrl}");
                        count++;
                    }
                }
            }

            var result = sb.ToString();
            return string.IsNullOrWhiteSpace(result.Trim())
                ? $"No results found for \"{query}\". Try a different search query."
                : result;
        }
        catch (Exception ex)
        {
            return $"Search failed for \"{query}\": {ex.Message}. Try a different query.";
        }
    }
}

/// <summary>
/// Simple note-taking tool that stores research findings in memory.
/// </summary>
sealed class Notepad
{
    private readonly List<(string Title, string Body)> _notes = [];

    public string AddNote(
        [Description("Short title for the note")] string title,
        [Description("The note content / research finding")] string body)
    {
        _notes.Add((title, body));
        return $"Note saved: \"{title}\" (total notes: {_notes.Count})";
    }

    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        for (var i = 0; i < _notes.Count; i++)
        {
            sb.AppendLine($"## Note {i + 1}: {_notes[i].Title}");
            sb.AppendLine(_notes[i].Body);
            sb.AppendLine();
        }
        return sb.ToString();
    }

    public void Clear() => _notes.Clear();
}

